/**
 * `agent-env.sh`: sourcing it gives a shell the trial agent's environment —
 * the pinned, non-secret variables plus the trial token, read from the
 * owner-only try-context.json at source time so the token never lands in this
 * file or in terminal scrollback.
 */
export const buildAgentEnvScript = (options: {
  pinnedEnv: Record<string, string>;
  contextPath: string;
}): string =>
  [
    "# Generated by `meticulous try`. Source it to give a shell this trial's",
    "# Meticulous environment: . ./agent-env.sh",
    ...Object.entries(options.pinnedEnv).map(
      ([name, value]) => `export ${name}=${shellQuote(value)}`,
    ),
    `METICULOUS_API_TOKEN="$(node -p 'require(process.argv[1]).apiToken' ${shellQuote(options.contextPath)})"`,
    "export METICULOUS_API_TOKEN",
    "",
  ].join("\n");

export const shellQuote = (value: string): string =>
  `'${value.replace(/'/g, `'\\''`)}'`;
